exports.CoreTaskFieldsFragmentDoc = (0, graphql_tag_1.default)`
  fragment CoreTaskFields on Task {
    id
    title
    description
    status
    ownerId
    ownerType
    ownerEmail
    ownerProfile {
      __typename
      ... on Profile {
        name
        email
        picture
      }
      ... on UserGroup {
        _id
        groupName: name
        handle
      }
    }
    meetingId
    meetingTimestamp
    meetingCaptionIndex
    createdById
    completedAt
    completedByUserId
    createdAt
    updatedAt
    hasChangedOwner
    generatedOwnerName
  }
`;
